vector<int> kahnTopological_12(const vector<vector<int>>& adj) { int V = adj.size(); vector<int> inDeg(V, 0); for (int u = 0; u < V; ++u) for (int v2 : adj[u]) ++inDeg[v2]; queue<int> q; for (int i = 0; i < V; ++i) if (inDeg[i] == 0) q.push(i); vector<int> res; while (!q.empty()) { int u = q.front(); q.pop(); res.push_back(u); for (int v2 : adj[u]) if (--inDeg[v2] == 0) q.push(v2); } return res; }
vector<int> outDegreeList_12(const vector<vector<int>>& adj) { int V = adj.size(); vector<int> deg(V, 0); for (int i = 0; i < V; ++i) deg[i] = adj[i].size(); return deg; }
